const { chromium, request } = require('@playwright/test');
const BASE = 'http://localhost:3000';
(async () => {
  const api = await request.newContext({ baseURL: BASE });
  const email = `explore-${Date.now()}@example.test`, password = 'Passw0rd!x1';
  await api.post('/api/Users/', { data: { email, password, passwordRepeat: password, securityQuestion: { id: 1 }, securityAnswer: 't' } });
  const login = await (await api.post('/rest/user/login', { data: { email, password } })).json();
  const { token, bid } = login.authentication;
  const H = { Authorization: `Bearer ${token}` };
  await api.post('/api/Addresss/', { headers: H, data: { fullName: 'Test Customer', mobileNum: 501234567, zipCode: '01001', streetAddress: '1 Khreshchatyk Street', city: 'Kyiv', state: 'Kyiv', country: 'Ukraine' } });
  await api.post('/api/Cards/', { headers: H, data: { fullName: 'Test Customer', cardNum: 4111111111111111, expMonth: 12, expYear: 2090 } });
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ baseURL: BASE });
  await ctx.addCookies([{ name: 'cookieconsent_status', value: 'dismiss', url: BASE }, { name: 'language', value: 'en', url: BASE }, { name: 'token', value: token, url: BASE }]);
  await ctx.addInitScript(([t, b]) => { localStorage.setItem('token', t); sessionStorage.setItem('bid', String(b)); }, [token, bid]);
  const page = await ctx.newPage();
  // login page visible text
  const lp = await browser.newPage(); await lp.context().addCookies([{ name: 'cookieconsent_status', value: 'dismiss', url: BASE }, { name: 'language', value: 'en', url: BASE }]);
  await lp.goto(BASE + '/#/login'); await lp.getByRole('button', { name: 'Login', exact: true }).waitFor();
  console.log('LOGIN FORM:', await lp.locator('#login-form, form, mat-card').first().innerText());
  console.log('LOGIN BTN:', await lp.locator('#loginButton').evaluate(e => e.outerHTML.slice(0, 400)));
  console.log('EMAIL LABEL:', await lp.locator('mat-label').allInnerTexts());
  // empty basket
  await page.goto('/#/basket');
  console.log('BASKET immediately:', JSON.stringify(await page.locator('app-basket').innerText().catch(() => '')));
  await page.waitForTimeout(2000);
  console.log('BASKET loaded empty:', JSON.stringify(await page.locator('app-basket').innerText()));
  // add items via UI
  await page.goto('/#/search?q=Eggfruit'); await page.getByRole('button', { name: 'Add to Basket' }).first().click(); await page.waitForTimeout(800);
  await page.getByRole('button', { name: 'Add to Basket' }).first().click(); await page.waitForTimeout(800);
  await page.goto('/#/search?q=Carrot'); await page.getByRole('button', { name: 'Add to Basket' }).first().click(); await page.waitForTimeout(800);
  console.log('SNACKBARS:', await page.locator('simple-snack-bar, .mat-mdc-snack-bar-container').evaluateAll(es => es.map(e => e.outerHTML.slice(0, 600))));
  await page.goto('/#/basket'); await page.waitForTimeout(1500);
  console.log('BASKET 2 items:', JSON.stringify(await page.locator('app-basket').innerText()));
  const rowId = await page.getByRole('row').nth(1).evaluate(e => { e.dataset.mark = 'old'; return e.outerHTML.slice(0, 300); });
  await page.getByRole('row').nth(1).getByRole('cell').nth(2).getByRole('button').last().click();
  await page.waitForTimeout(1500);
  console.log('old row still attached after plus:', await page.locator('[data-mark=old]').count());
  await page.locator('button', { hasText: 'Checkout' }).click();
  await page.getByRole('row').filter({ hasText: '1 Khreshchatyk' }).getByRole('radio').click();
  await page.locator('button', { hasText: 'Continue' }).click();
  await page.getByRole('row').filter({ hasText: 'One Day Delivery' }).getByRole('radio').click();
  await page.locator('button', { hasText: 'Continue' }).click();
  await page.waitForTimeout(1500);
  console.log('PAYMENT:', JSON.stringify(await page.locator('app-payment').innerText()));
  await page.getByRole('row').filter({ hasText: '1111' }).getByRole('radio').click();
  await page.locator('button', { hasText: 'Continue' }).click();
  await page.waitForTimeout(1500);
  console.log('SUMMARY:', JSON.stringify(await page.locator('app-order-summary').innerText()));
  console.log('SUMMARY cards html:', await page.locator('app-order-summary mat-card').evaluateAll(es => es.map(e => e.outerHTML.slice(0, 1500))));
  await page.locator('button', { hasText: 'Place your order and pay' }).click();
  await page.waitForTimeout(2000);
  console.log('COMPLETION:', JSON.stringify(await page.locator('app-order-completion').innerText()));
  console.log('COMPLETION rows:', await page.getByRole('row').evaluateAll(es => es.map(e => e.innerText)));
  console.log('COMPLETION cells product row:', await page.getByRole('row').filter({ hasText: 'Eggfruit' }).getByRole('cell').allInnerTexts());
  await page.goto('/#/basket');
  console.log('BASKET after order immediately:', JSON.stringify(await page.locator('app-basket').innerText().catch(() => '')));
  await page.waitForTimeout(2000);
  console.log('BASKET after order loaded:', JSON.stringify(await page.locator('app-basket').innerText()));
  await browser.close();
})();
EOF
