async (page) => {
  const BASE = 'http://localhost:3000';
  await page.goto(BASE + '/#/basket'); await page.waitForTimeout(500);
  await page.goto(BASE + '/#/search?q=Apple');
  for (let i = 0; i < 5; i++) { await page.getByRole('button', { name: 'Add to Basket' }).first().click(); await page.waitForTimeout(700); }
  await page.goto(BASE + '/#/basket'); await page.waitForTimeout(1500);
  const resp = page.waitForResponse(r => r.url().includes('/rest/basket/') && r.request().method() === 'GET');
  await page.getByRole('row').filter({ hasText: 'Apple Juice' }).getByRole('cell').nth(2).getByRole('button').last().click();
  const t0 = Date.now();
  const msg = page.getByText('You can order only up to 5 items of this product.');
  await msg.first().waitFor();
  const html = await msg.first().evaluate(e => e.closest('mat-snack-bar-container, mat-error, div')?.outerHTML.slice(0, 600));
  let reloaded = 'no';
  try { await Promise.race([resp, new Promise((_, rej) => setTimeout(rej, 2000))]); reloaded = 'yes'; } catch {}
  await msg.first().waitFor({ state: 'hidden', timeout: 30000 });
  const hiddenAfter = Date.now() - t0;
  const r2 = await page.request.get(BASE + '/rest/basket/6').catch(() => null);
  return { html, hiddenAfter, reloadedOnError: reloaded };
}

