121	/** The basket `/#/basket`. */
122	export class BasketPage {
123	  constructor(private readonly page: Page) {}
124	
125	  row(name: string) {
126	    return this.page.getByRole('row').filter({ hasText: name });
127	  }
128	
129	  /** The quantity cell is the third cell: minus button, quantity, plus button. */
130	  private quantityCell(name: string) {
131	    return this.row(name).getByRole('cell').nth(2);
132	  }
133	
134	  increase(name: string) {
135	    return this.quantityCell(name).getByRole('button').last();
136	  }
137	
138	  decrease(name: string) {
139	    return this.quantityCell(name).getByRole('button').first();
140	  }
141	
142	  /** The trash button is in the last cell of the row. */
143	  remove(name: string) {
144	    return this.row(name).getByRole('cell').last().getByRole('button');
145	  }
146	
147	  get checkoutButton() {
148	    return this.page.locator('button', { hasText: 'Checkout' });
149	  }
150	
151	  /** Rows with cells. The table also has an empty row without cells. */
152	  get productRows() {
153	    return this.page.getByRole('row').filter({ has: this.page.getByRole('cell') });
154	  }
155	
156	  /**
157	   * Clicks the button in the row of the product and waits until the basket shows the result from the server.
158	   * After each change, the basket loads its content again and draws all rows again, so the old row goes away.
159	   */
160	  private async clickInRowAndWaitForReload(name: string, button: Locator): Promise<void> {
161	    const shownRow = await this.row(name).elementHandle();
162	    await button.click();
163	    await shownRow?.waitForElementState('hidden');
164	  }
165	
166	  async clickIncrease(name: string): Promise<void> {
167	    await this.clickInRowAndWaitForReload(name, this.increase(name));
168	  }
169	
170	  async clickDecrease(name: string): Promise<void> {
171	    await this.clickInRowAndWaitForReload(name, this.decrease(name));
172	  }
173	
174	  async expectRow(name: string, quantity: number): Promise<void> {
175	    await expect(this.row(name)).toBeVisible();
176	    await expect(this.quantityCell(name).getByText(String(quantity), { exact: true })).toBeVisible();
177	  }
178	
179	  async expectNoRow(name: string): Promise<void> {
180	    await expect(this.row(name)).toHaveCount(0);
181	  }
182	
183	  async expectProductRowCount(count: number): Promise<void> {
184	    await expect(this.productRows).toHaveCount(count);
185	  }
186	
187	  /**
188	   * Opens the basket and checks that it is empty. An empty basket looks the same before and after
189	   * the content is loaded, so the check waits for the content that the server returns.
190	   */
191	  async expectEmptyWhenOpened(open: () => Promise<void>): Promise<void> {
192	    // A request, not a response: a basket request that started before the page opened can still be in progress.
193	    const loading = this.page.waitForRequest(isBasketContentRequest);
194	    await open();
195	    const response = await (await loading).response();
196	    if (!response) {
197	      throw new Error('The basket page got no response with the basket content');
198	    }
199	    const content = (await response.json()) as BasketContent;
200	    expect(content.data.Products.map((product) => product.name), 'products in the basket on the server').toEqual([]);
201	    await expect(this.productRows).toHaveCount(0);
202	    await expect(this.checkoutButton).toBeDisabled();
203	  }
204	
205	  async expectTotal(total: string): Promise<void> {
206	    await expect(this.page.getByText(totalPrice(total))).toBeVisible();
207	  }
208	}
